"""Source for the Malayalam, Telugu, Kannada and Hindi UI strings, plus new keys for English and Tamil.
Sanskrit-derived name lists (60 samvatsaras, yogas, karanas) are transliterated into each script
from one Harvard-Kyoto source so spellings stay consistent.
Run from the repo root:  python3 src/i18n_src.py   ->  writes src/i18n.js
"""
import json
from indic_transliteration import sanscript as S

SCRIPT = {'hi': S.DEVANAGARI, 'te': S.TELUGU, 'kn': S.KANNADA, 'ml': S.MALAYALAM}
import re as _re
def tr(s, l):
    out = S.transliterate(s, S.HK, SCRIPT[l])
    if l == 'ml':  # modern Malayalam: chillu letters and the ൗ vowel sign
        out = out.replace('ൌ', 'ൗ')
        out = _re.sub('ര്(?=[\u0D15-\u0D39])', 'ർ', out)
        for a, b in [('ന്', 'ൻ'), ('ണ്', 'ൺ'), ('ര്', 'ർ'), ('ല്', 'ൽ'), ('ള്', 'ൾ'), ('മ്', 'ം')]:
            out = _re.sub(a + '(?![\u0D00-\u0D7F])', b, out)
    return out
def final_m(s, l):
    return {'hi': _re.sub('म्$', 'म', s), 'te': _re.sub('మ్$', 'ం', s), 'kn': _re.sub('ಮ್$', 'ಂ', s),
            'ml': _re.sub('മ്$', 'ം', s)}[l]

